/**
 * Input 컴포넌트
 * 유효성 검사 및 에러 메시지 표시
 */
export function initInput(root = document) {
  const inputs = root.querySelectorAll('[data-lg-input]');

  inputs.forEach((wrapper) => {
    const field = wrapper.querySelector('.lg-input__field');
    const errorEl = wrapper.querySelector('.lg-input__error');
    if (!field) return;

    const validate = () => {
      const isRequired = field.hasAttribute('required');
      const isEmpty = field.value.trim() === '';
      const isInvalid = isRequired && isEmpty;

      field.classList.toggle('lg-input__field--error', isInvalid);
      if (errorEl) {
        errorEl.hidden = !isInvalid;
      }

      return !isInvalid;
    };

    field.addEventListener('blur', validate);
    field.addEventListener('input', () => {
      if (field.classList.contains('lg-input__field--error')) {
        validate();
      }
    });
  });
}

export default initInput;
